/**
 * Heuristics for attribute values that were generated by a framework or build tool.
 * Those values change between builds or page loads, so a locator built on them breaks.
 *
 * Examples that count as generated: ember123, :r1:, react-select-3-input, css-1x2y3z,
 * sc-bdVaJa, mui-12345, 3f2a9c1e-5b7d-4e8a, a very long value.
 * Examples that do not: pokedex, login-submit, email, input-12, search.
 */
const GENERATED_PREFIXES = /^(ember|react-|:r|mui-|css-|sc-|jsx-|ng-|svelte-|__|headlessui-|radix-)/i;

export function looksGenerated(value: string | null | undefined): boolean {
  if (!value) return true;
  const v = value.trim();
  if (v.length === 0 || v.length > 50) return true;
  if (GENERATED_PREFIXES.test(v)) return true;
  if (v.includes(':')) return true; // React 18 useId(): :r1:
  if (/[«»]/.test(v)) return true; // React 19.0 useId(): «r1»
  if (/^_r_[a-z0-9]*_?$/i.test(v)) return true; // React 19.1+ useId(): _r_c_
  if (/\d{3,}/.test(v)) return true; // long digit runs are usually counters or timestamps
  // Hex or UUID chunks with at least one digit and one letter, e.g. 3f2a9c, a1b2c3d4
  if (/(^|[-_])(?=[0-9a-f]*\d)(?=[0-9a-f]*[a-f])[0-9a-f]{6,}($|[-_])/i.test(v)) return true;
  // Random tokens: any 8+ character piece mixing digits, capitals and lowercase,
  // e.g. Google's per-load ids like _xCG5apS3Hrzw0PEPqMW4yQI_60. Real names rarely mix all three.
  for (const token of v.split(/[-_.:]/)) {
    if (token.length >= 8 && /\d/.test(token) && /[A-Z]/.test(token) && /[a-z]/.test(token)) return true;
  }
  // Hashed class-like suffixes: letters + mixed case/digits run of 5+, e.g. sc-AxjAm, x1a2b3c
  if (/[-_][a-zA-Z0-9]{5,}$/.test(v) && /\d/.test(v.split(/[-_]/).pop() ?? '') && /[a-z]/i.test(v.split(/[-_]/).pop() ?? '')) {
    return true;
  }
  return false;
}
